package com.wizzadrds.theworldremembers.voice; import java.util.*; public final class VoiceScheduler { private final int capacity; private final PriorityQueue<VoiceJob> queue=new PriorityQueue<>(Comparator.comparingInt((VoiceJob j)->j.priority().ordinal()).reversed().thenComparingLong(VoiceJob::createdTick)); private final Set<UUID> active=new HashSet<>(); public VoiceScheduler(int capacity){if(capacity<1)throw new IllegalArgumentException("capacity");this.capacity=capacity;} public boolean submit(VoiceJob job){if(active.contains(job.npcId()))return false;if(queue.size()>=capacity){VoiceJob lowest=queue.stream().min(Comparator.comparingInt((VoiceJob j)->j.priority().ordinal()).thenComparingLong(VoiceJob::createdTick)).orElse(null);if(lowest==null||job.priority().ordinal()<=lowest.priority().ordinal())return false;queue.remove(lowest);}queue.add(job);return true;} public VoiceJob startNext(){VoiceJob job=queue.poll();if(job!=null)active.add(job.npcId());return job;} public void finish(UUID npcId){active.remove(npcId);} public int queued(){return queue.size();} public int active(){return active.size();} }
